#!/usr/bin/env python3
import subprocess, sys, os, json
EXE="/workspace/executable"
env=dict(os.environ); env["HOME"]="/tmp/w/home"
def run(snip, exe=EXE, args=None, bash=False):
    if bash: cmd=["/bin/bash","-c",snip]
    else: cmd=[exe,"--norc","-c",snip]
    if args: cmd=cmd[:1]+args+cmd[1:]
    try:
        p=subprocess.run(cmd,capture_output=True,text=True,timeout=10,stdin=subprocess.DEVNULL,env=env,cwd="/tmp/w")
        return p.returncode,p.stdout,p.stderr
    except subprocess.TimeoutExpired:
        return "TIMEOUT","",""
def clean(e):
    # strip backtrace lines
    out=[]
    for l in e.split("\n"):
        if l.startswith("note: run with") or l.startswith("stack backtrace:"): break
        out.append(l)
    return "\n".join(out)
def show(snip, cmp_bash=False):
    rc,o,e=run(snip)
    print("=== "+repr(snip))
    print("rc="+str(rc))
    if o: print("OUT<<<"+o+">>>")
    if e: print("ERR<<<"+clean(e)+">>>")
    if not o and not e: print("(no output)")
    if cmp_bash:
        rc2,o2,e2=run(snip,bash=True)
        print("bash rc="+str(rc2)+(" OUT<<<"+o2+">>>" if o2 else "")+(" ERR<<<"+e2.strip()+">>>" if e2 else ""))
    print()
if __name__=="__main__":
    for a in sys.argv[1:]: show(a)
