import json,sys
from collections import defaultdict
files=sys.argv[1:] or ['/tmp/w/h1.json']
lists=[]
for f in files:
    for r in json.load(open(f)):
        if r['p']: lists.append(tuple(r['p']))
        if r['n']: lists.append(tuple(r['n']))
uniq=set(lists)
print("distinct positive/negative lists:",len(uniq))
# build edges
edges=defaultdict(set); nodes=set()
bad=[]
for L in uniq:
    for i in range(len(L)):
        nodes.add(L[i])
        for j in range(i+1,len(L)):
            edges[L[i]].add(L[j])
# check consistency (no A<B and B<A)
for a in list(edges):
    for b in edges[a]:
        if a in edges.get(b,()): bad.append((a,b))
print("contradictions:",bad)
# topo sort
import itertools
indeg={n:0 for n in nodes}
for a in edges:
    for b in edges[a]:
        indeg[b]=indeg.get(b,0)+1
order=[]; avail=sorted([n for n in nodes if indeg[n]==0])
ambig=[]
while avail:
    if len(avail)>1: ambig.append(list(avail))
    n=avail.pop(0); order.append(n)
    for b in sorted(edges.get(n,())):
        indeg[b]-=1
        if indeg[b]==0: avail.append(b)
    avail=sorted(avail)
print("total rules seen:",len(nodes))
print("topo order:")
for i,n in enumerate(order): print(" %2d %s"%(i,n))
print("ambiguity points (sets where >1 candidate available):")
for a in ambig: print("  ",a)
